SELECT COUNT(1) > 0 FROM skill_manage
WHERE retrieval_name = #{retrievalName}
  AND owner_user_id = #{ownerUserId}
  AND status = 'ACTIVE'
  AND deleted_at IS NULL

SELECT s.id, s.name, s.description, s.content, s.category, s.tags,
       s.owner_user_id, s.status, s.like_count, s.retrieval_name, s.created_at, s.updated_at, s.deleted_at
FROM skill_manage s


        INNER JOIN skill_reference r ON r.target_skill_id = s.id AND r.creator = #{userId}
        LEFT JOIN skill_user_disable d ON d.skill_id = s.id AND d.user_id = #{userId}


        INNER JOIN skill_like l ON l.skill_id = s.id AND l.user_id = #{userId}





            s.owner_user_id = #{userId} AND s.status = 'ACTIVE'


            s.status = 'ACTIVE' AND d.skill_id IS NULL


            s.status = 'ACTIVE'
            AND (
                s.owner_user_id = #{userId}
                OR s.id NOT IN (SELECT skill_id FROM skill_publish WHERE status IN ('PENDING', 'REJECTED'))
            )



        AND s.category = #{category}


        AND (',' || s.tags || ',') LIKE ('%,' || #{tag} || ',%')


        AND (s.name LIKE CONCAT('%', #{keyword}, '%')
          OR s.description LIKE CONCAT('%', #{keyword}, '%'))




        ORDER BY s.updated_at DESC


        ORDER BY s.name ASC


        ORDER BY s.like_count DESC, s.updated_at DESC


LIMIT #{effectiveLimit} OFFSET #{effectiveOffset}

