INSERT INTO skill_user_disable (skill_id, user_id)
SELECT #{skillId}, #{userId}
WHERE NOT EXISTS (
    SELECT 1 FROM skill_user_disable WHERE skill_id = #{skillId} AND user_id = #{userId}
)

